// 한국어 PDF용 CMap (pdf.js), 파일 하나로 동작하도록 내장
(function(root){var M={"Adobe-Korea1-UCS2": "", "KSC-EUC-H": "", "KSCms-UHC-H": "", "KSCms-UHC-HW-H": "", "UniKS-UCS2-H": "", "UniKS-UTF16-H": "", "UniKS-UTF8-H": ""};
function b64(s){var b=atob(s),u=new Uint8Array(b.length);for(var i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u;}
function F(){}F.prototype.fetch=function(o){var n=o.name;if(!M[n])return Promise.reject(new Error('CMap '+n+' 없음'));return Promise.resolve({cMapData:b64(M[n]),compressionType:1});};
root.EmbeddedCMapFactory=F;})(typeof window!=='undefined'?window:globalThis);
